def max_repeated_substring_length(N, S):
    from collections import defaultdict

    # Dictionary to store the count of each substring
    substring_count = defaultdict(int)

    # Variable to store the maximum length of repeated substrings
    max_length = 0

    # Iterate over all possible starting indices and lengths of substrings
    for start in range(N):
        for length in range(1, N - start + 1):
            substring = S[start:start + length]
            substring_count[substring] += 1
            if substring_count[substring] > 1:
                max_length = max(max_length, length)

    return max_length

