def can_reach_all_points(points):
    N = len(points)
    if N == 1:
        return 1, [0], ['L']

    for m in range(1, 41):
        for lengths in combinations_with_replacement(range(1, 10**12 + 1), m):
            if sum(lengths) == 0:
                continue
            for modes in product('LRDU', repeat=m):
                x, y = 0, 0
                valid = True
                for i in range(m):
                    if modes[i] == 'L':
                        x -= lengths[i]
                    elif modes[i] == 'R':
                        x += lengths[i]
                    elif modes[i] == 'D':
                        y -= lengths[i]
                    elif modes[i] == 'U':
                        y += lengths[i]
                    if (x, y) not in points:
                        valid = False
                        break
                if valid:
                    return m, lengths, [''.join(modes)]

    return -1

def combinations_with_replacement(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if r > n:
        return
    indices = list(range(r))
    yield tuple(pool[i] for i in indices)
    while True:
        for i in reversed(range(r)):
            if indices[i] != i + n - r:
                break
        else:
            return
        indices[i] += 1
        for j in range(i+1, r):
            indices[j] = indices[j-1] + 1
        yield tuple(pool[i] for i in indices)

def product(*args, repeat=1):
    pools = [tuple(pool) for pool in args] * repeat
    result = [[]]
    for pool in pools:
        result = [x + [y] for x in result for y in pool]
    for prod in result:
        yield tuple(prod)

