def is_valid_elevator_sequence(N, A, B):
    # Initialize the elevator state and the set of floors with people getting on/off
    elevator_state = [0] * (2 * N + 1)
    floors_with_people = set()

    for i in range(N):
        a, b = A[i], B[i]

        if a != -1 and b != -1:
            # Update the elevator state for the entire journey of person i
            for floor in range(a, b):
                elevator_state[floor] += 1
                if elevator_state[floor] > N:
                    return "No"
                floors_with_people.add(floor)
        elif a != -1:
            # Mark the floor as having someone get on
            floors_with_people.add(a)
        elif b != -1:
            # Mark the floor as having someone get off
            floors_with_people.add(b)

    # Check if the elevator state is consistent
    for floor in range(1, 2 * N + 1):
        if floor in floors_with_people and elevator_state[floor] == 0:
            return "No"

    return "Yes"

