def can_form_valid_sequence(N, A, B):
    # Dictionary to keep track of the number of times each floor is visited
    floor_visits = {}

    # Iterate through the list of persons
    for i in range(N):
        a, b = A[i], B[i]

        # If both A_i and B_i are present, update the floor visits
        if a != -1 and b != -1:
            if a not in floor_visits:
                floor_visits[a] = 0
            if b not in floor_visits:
                floor_visits[b] = 0
            floor_visits[a] += 1
            floor_visits[b] -= 1

        # If A_i is missing, try to assign a valid value
        elif a == -1:
            for j in range(1, 2*N + 1):
                if j not in floor_visits:
                    A[i] = j
                    if b != -1:
                        floor_visits[j] = 0
                        floor_visits[b] = 0
                        floor_visits[j] += 1
                        floor_visits[b] -= 1
                    break

        # If B_i is missing, try to assign a valid value
        elif b == -1:
            for j in range(1, 2*N + 1):
                if j not in floor_visits:
                    B[i] = j
                    if a != -1:
                        floor_visits[a] = 0
                        floor_visits[j] = 0
                        floor_visits[a] += 1
                        floor_visits[j] -= 1
                    break

    # Check if the sequence is valid
    current_visits = 0
    for floor in range(1, 2*N + 1):
        if floor in floor_visits:
            current_visits += floor_visits[floor]
            if current_visits < 0:
                return "No"

