def count_ways(N, M, K):
    if K == 0:
        return pow(M, N, MOD)

    dp = [[[0] * (K + 1) for _ in range(M + 1)] for _ in range(N + 1)]

    for j in range(1, M + 1):
        dp[1][j][0] = 1

    for i in range(2, N + 1):
        for j in range(1, M + 1):
            for k in range(K + 1):
                dp[i][j][k] = sum(dp[i-1][m][k] for m in range(1, M + 1) if m != j) % MOD
                if k > 0:
                    dp[i][j][k] = (dp[i][j][k] + dp[i-1][j][k-1]) % MOD

    result = sum(dp[N][j][k] for j in range(1, M + 1) for k in range(K + 1)) % MOD
    return result

