def count_sequences(N, M):
    if N == 1:
        return 1 if M == 1 else 0

    if M == 1:
        return 1

    # Factorize M
    factors = []
    for i in range(2, int(M**0.5) + 1):
        while M % i == 0:
            factors.append(i)
            M //= i
    if M > 1:
        factors.append(M)

    # Count the number of distinct factors
    distinct_factors = set(factors)

    # Initialize DP table
    dp = [[0] * (M + 1) for _ in range(N + 1)]
    dp[0][1] = 1

    # Fill DP table
    for i in range(1, N + 1):
        for j in range(1, M + 1):
            for factor in distinct_factors:
                if j % factor == 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j // factor]) % MOD

    return dp[N][M]

