def knight_ways(X, Y):
    # Initialize the dp array with zeros
    dp = [[0] * (Y + 1) for _ in range(X + 1)]

    # Base case: there is one way to be at the origin
    dp[0][0] = 1

    # Fill the dp array
    for i in range(X + 1):
        for j in range(Y + 1):
            if i >= 1 and j >= 2:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 2]) % MOD
            if i >= 2 and j >= 1:
                dp[i][j] = (dp[i][j] + dp[i - 2][j - 1]) % MOD

    # The answer is the number of ways to reach (X, Y)
    return dp[X][Y]

