def is_valid_move(H, W, y, x):
    return 1 <= y <= H and 1 <= x <= W

def solve(H, W, grid):
    operations = []
    for y in range(1, H + 1):
        for x in range(1, W + 1):
            if grid[y-1][x-1] % 2 != 0:
                found = False
                for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny, nx = y + dy, x + dx
                    if is_valid_move(H, W, ny, nx) and grid[ny-1][nx-1] % 2 == 0:
                        operations.append((y, x, ny, nx))
                        grid[y-1][x-1] -= 1
                        grid[ny-1][nx-1] += 1
                        found = True
                        break
                if not found:
                    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ny, nx = y + dy, x + dx
                        if is_valid_move(H, W, ny, nx):
                            operations.append((y, x, ny, nx))
                            grid[y-1][x-1] -= 1
                            grid[ny-1][nx-1] += 1
                            found = True
                            break
                if not found:
                    raise ValueError("Impossible to make all cells even")
    return operations

