def find_paths(tree, n):
    paths = defaultdict(list)
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            path = []
            dfs(i, -1, path, tree)
            if j in path:
                paths[(i, j)] = path
            path = []
            dfs(j, -1, path, tree)
            if i in path:
                paths[(i, j)] = path
    return paths

def is_valid_painting(painting, restrictions, paths):
    for u, v in restrictions:
        path = paths[(u, v)]
        for i in range(len(path) - 1):
            if (path[i], path[i + 1]) in painting or (path[i + 1], path[i]) in painting:
                break
        else:
            return False
    return True

def count_valid_paintings(tree, n, restrictions):
    paths = find_paths(tree, n)
    count = 0
    total_paintings = 2 ** (n - 1)
    for i in range(total_paintings):
        painting = []
        for j in range(n - 1):
            if i & (1 << j):
                painting.append((j + 1, j + 2))
            else:
                painting.append((j + 2, j + 1))
        if is_valid_painting(painting, restrictions, paths):
            count += 1
    return count

