    if valid:
        dp[node][mask] = 1
    else:
        dp[node][mask] = 0

    for neighbor in adj[node]:
        if neighbor == parent:
            continue
        dp[node][mask] += dfs(neighbor, node, mask, restrictions, dp, adj)

