def dfs(node, parent, color, tree, restrictions, valid):
    for neighbor in tree[node]:
        if neighbor == parent:
            continue
        if color[node] == color[neighbor]:
            return False
        if (node, neighbor) in restrictions or (neighbor, node) in restrictions:
            if color[node] == 0:
                color[neighbor] = 1
            else:
                color[neighbor] = 0
        if not dfs(neighbor, node, color, tree, restrictions, valid):
            return False
    return True

def count_valid_paintings(N, edges, M, restrictions):
    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    color = [0] * (N + 1)
    valid = [False] * (1 << N)

    def backtrack(node, parent, mask):
        if node == N + 1:
            if all(valid[mask]):
                return 1
            return 0

        count = 0
        for neighbor in tree[node]:
            if neighbor == parent:
                continue
            if mask & (1 << (node - 1)) == 0:
                color[node] = 0
                color[neighbor] = 1
                if dfs(node, parent, color, tree, restrictions, valid):
                    count += backtrack(neighbor, node, mask | (1 << (node - 1)))
                color[node] = 1
                color[neighbor] = 0
                if dfs(node, parent, color, tree, restrictions, valid):
                    count += backtrack(neighbor, node, mask | (1 << (node - 1)))
            else:
                if dfs(node, parent, color, tree, restrictions, valid):
                    count += backtrack(neighbor, node, mask)
        return count

    return backtrack(1, -1, 0)

