import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return divs

def are_coprime(divs):
    for a, b in combinations(divs, 2):
        if math.gcd(a, b) != 1:
            return False
    return True

def max_coprime_divisors(A, B):
    g = gcd(A, B)
    divs = divisors(g)
    max_coprime = 0
    for r in range(1, len(divs) + 1):
        for comb in combinations(divs, r):
            if are_coprime(comb):
                max_coprime = max(max_coprime, r)
    return max_coprime

