import math

def prime_factors(n):
    i = 2
    factors = {}
    while i * i <= n:
        while (n % i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def divisors(n):
    factors = prime_factors(n)
    divs = [1]
    for prime, exp in factors.items():
        divs.extend([prime**i * d for i in range(1, exp + 1) for d in divs])
    return divs

def gcd(a, b):
    return math.gcd(a, b)

def coprime_divisors(a, b):
    common_gcd = gcd(a, b)
    divs = divisors(common_gcd)
    coprime_divs = [1]
    for d in divs[1:]:
        if all(math.gcd(d, cd) == 1 for cd in coprime_divs):
            coprime_divs.append(d)
    return coprime_divs

