from collections import Counter

def prime_factors(n):
    factors = []
    # Divide by 2 until n is odd
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # Check for odd factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        factors.append(n)
    return factors

def max_coprime_divisors(A, B):
    gcd = math.gcd(A, B)
    factors = prime_factors(gcd)
    factor_counts = Counter(factors)
    coprime_divisors = 1
    for count in factor_counts.values():
        coprime_divisors *= (count + 1)
    return coprime_divisors

