def max_coprime_divisors(A, B):
    # Find the GCD of A and B
    g = gcd(A, B)

    # Get the prime factors of the GCD
    factors = prime_factors(g)

    # Use a set to store the unique prime factors
    unique_factors = set(factors)

    # The number of unique prime factors is the maximum number of coprime divisors
