import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_coprime_divisors(n):
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return divisors

def max_coprime_divisors(A, B):
    g = gcd(A, B)
    divisors = find_coprime_divisors(g)
    coprime_count = 0
    used = [False] * len(divisors)

    for i in range(len(divisors)):
        if not used[i]:
            coprime_count += 1
            for j in range(i + 1, len(divisors)):
                if gcd(divisors[i], divisors[j]) == 1:
                    used[j] = True

    return coprime_count

