from collections import defaultdict

def prime_factors(n):
    i = 2
    factors = defaultdict(int)
    while i * i <= n:
        while (n % i) == 0:
            factors[i] += 1
            n //= i
        i += 1
    if n > 1:
        factors[n] += 1
    return factors

def max_coprime_divisors(A, B):
    gcd = math.gcd(A, B)
    factors = prime_factors(gcd)
    return len(factors)

