import math

def prime_factors(n):
    factors = set()
    # Check for number of 2s in n
    while n % 2 == 0:
        factors.add(2)
        n = n // 2
    # Check for other primes
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.add(i)
            n = n // i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        factors.add(n)
    return factors

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_coprime_divisors(A, B):
    gcd_value = gcd(A, B)
    return len(prime_factors(gcd_value))

