def count_distinct_matrices(N, K, matrix):
    from itertools import combinations

    # Function to check if a swap is valid
    def is_valid_swap(matrix, x, y, is_row):
        if is_row:
            for i in range(N):
                if matrix[i][x] + matrix[i][y] > K:
                    return False
        else:
            for i in range(N):
                if matrix[x][i] + matrix[y][i] > K:
                    return False
        return True

    # Function to perform a swap
    def swap(matrix, x, y, is_row):
        if is_row:
            matrix[x], matrix[y] = matrix[y], matrix[x]
        else:
            for i in range(N):
                matrix[i][x], matrix[i][y] = matrix[i][y], matrix[i][x]
        return matrix

    # Set to store unique matrices
    unique_matrices = set()

    # Add the original matrix
    unique_matrices.add(tuple(map(tuple, matrix)))

    # Try all possible swaps of columns
    for x, y in combinations(range(N), 2):
        if is_valid_swap(matrix, x, y, False):
            new_matrix = swap(matrix, x, y, False)
            unique_matrices.add(tuple(map(tuple, new_matrix)))

    # Try all possible swaps of rows
    for x, y in combinations(range(N), 2):
        if is_valid_swap(matrix, x, y, True):
            new_matrix = swap(matrix, x, y, True)
            unique_matrices.add(tuple(map(tuple, new_matrix)))

    # Return the number of unique matrices modulo 998244353
    return len(unique_matrices) % MOD

