def count_valid_matrices(N, K, matrix):
    from collections import defaultdict

    # Initialize DP table
    dp = defaultdict(int)
    dp[(tuple(matrix[0]),)] = 1

    for i in range(1, N):
        new_dp = defaultdict(int)
        for key, count in dp.items():
            current_row = list(key)
            for j in range(i):
                if current_row[j] + current_row[i] <= K:
                    new_row = current_row[:]
                    new_row[j], new_row[i] = new_row[i], new_row[j]
                    new_key = tuple(new_row)
                    new_dp[new_key] = (new_dp[new_key] + count) % MOD
        dp = new_dp

    # Count all valid matrices
    total = 0
    for key, count in dp.items():
        total = (total + count) % MOD

    return total

