def count_valid_matrices(N, K, matrix):
    # Initialize the DP table
    dp = [[0] * (1 << N) for _ in range(1 << N)]
    dp[0][0] = 1

    # Iterate over all possible states of rows and columns
    for row_state in range(1 << N):
        for col_state in range(1 << N):
            # Check if the current state is valid
            valid = True
            for i in range(N):
                for j in range(N):
                    if (row_state & (1 << i)) and (col_state & (1 << j)):
                        if matrix[i][j] + matrix[i][j] > K:
                            valid = False
                            break
                if not valid:
                    break
            if not valid:
                continue

            # Update the DP table
            dp[row_state][col_state] = (dp[row_state][col_state] + dp[row_state ^ (1 << i)][col_state]) % MOD
            dp[row_state][col_state] = (dp[row_state][col_state] + dp[row_state][col_state ^ (1 << j)]) % MOD

    # The result is the number of valid matrices
    return dp[(1 << N) - 1][(1 << N) - 1]

