def count_valid_matrices(N, K, matrix):
    count = 0
    rows = list(permutations(range(N)))
    cols = list(permutations(range(N)))

    for r in rows:
        for c in cols:
            new_matrix = [[matrix[r[i]][c[j]] for j in range(N)] for i in range(N)]
            if is_valid(new_matrix, K):
                count = (count + 1) % MOD
