def count_abc_numbers(S):
    from collections import Counter

    # Count occurrences of A, B, C, and '?'
    count = Counter(S)
    A_count = count['A']
    B_count = count['B']
    C_count = count['C']
    Q = count['?']

    # Calculate the number of valid triples (i, j, k)
    total_triples = 0

    # Case 1: No '?' characters
    if Q == 0:
        total_triples = A_count * (A_count - 1) * (A_count - 2) // 6 + \
                       B_count * (B_count - 1) * (B_count - 2) // 6 + \
                       C_count * (C_count - 1) * (C_count - 2) // 6
    else:
        # Case 2: There are '?' characters
        # Calculate the number of ways to choose positions for A, B, and C
        for a in range(A_count + 1):
            for b in range(B_count + 1):
                for c in range(C_count + 1):
                    if a + b + c == A_count + B_count + C_count:
                        # Calculate the number of ways to choose positions for '?' characters
                        remaining_positions = len(S) - (a + b + c)
                        ways_to_choose_positions = remaining_positions * (remaining_positions - 1) * (remaining_positions - 2) // 6
                        # Calculate the number of valid triples for the current combination
                        valid_triples = a * (a - 1) * (a - 2) // 6 + \
                                       b * (b - 1) * (b - 2) // 6 + \
                                       c * (c - 1) * (c - 2) // 6
                        # Add to the total number of triples
                        total_triples = (total_triples + valid_triples * ways_to_choose_positions) % MOD

    return total_triples

