        mid = (left + right) // 2
        if sum(grid[j][0] == '1' for j in range(mid + 1)) <= k:
            right = mid
        else:
            left = mid + 1

    if left == rows - 1:
        return False

    # Check vertical cuts
    for j in range(1, cols):
        if sum(grid[i][j] == '1' for i in range(left + 1)) <= k:
            return True

    return False

def min_cuts_to_divide(grid, rows, cols, k):
    total_white = count_white_squares(grid, rows, cols)
    if total_white <= k:
        return 0

    left, right = 0, rows - 1
    while left < right:
        mid = (left + right) // 2
        if can_divide(grid, rows, cols, k, mid):
            right = mid
        else:
            left = mid + 1

    return left

