def bfs_check_bipartite(graph, start, colors):
    queue = deque([start])
    colors[start] = 0
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in colors:
                colors[neighbor] = 1 - colors[node]
                queue.append(neighbor)
            elif colors[neighbor] == colors[node]:
                return False
    return True

def hopcroft_karp(graph, n, m):
    match = [-1] * m
    dist = [0] * n
    def bfs():
        for i in range(n):
            if match[i] == -1:
                dist[i] = 0
                queue = deque([i])
                found = False
                while queue:
                    u = queue.popleft()
                    for v in graph[u]:
                        if match[v] == -1:
                            match[v] = u
                            match[u] = v
                            found = True
                            break
                        elif dist[match[v]] == dist[u] + 1:
                            dist[match[v]] = -1
                            queue.append(match[v])
                if found:
                    return True
        return False

    max_match = 0
    while bfs():
        for i in range(n):
            if match[i] == -1 and dist[i] == 0:
                if dfs(i):
                    max_match += 1
    return max_match

