    for i in range(H):
        for j in range(W):
            if i > 0:
                graph[(i, j)].append((i - 1, j))
                graph[(i - 1, j)].append((i, j))
            if j > 0:
                graph[(i, j)].append((i, j - 1))
                graph[(i, j - 1)].append((i, j))

    # Check if the graph is bipartite
    colors = {}
    for i in range(H):
        for j in range(W):
            if (i, j) not in colors:
                if not bfs_check_bipartite(graph, (i, j), colors):
                    return -1  # Not possible to divide into blocks with K or fewer white squares

    # Use Hopcroft-Karp to find the minimum number of cuts
    n = H * W
    m = n // 2
    return hopcroft_karp(graph, n, m)

