def min_cuts(H, W, K, grid):
    # Initialize the DP table with infinity
    dp = [[float('inf')] * W for _ in range(H)]

    # Base case: no cuts needed for a single cell
    for i in range(H):
        for j in range(W):
            dp[i][j] = 0 if grid[i][j] == 0 else 1

    # Fill the DP table
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 0:
                continue
            for x in range(i):
                if sum(grid[x][j] for x in range(i, H)) <= K:
                    dp[i][j] = min(dp[i][j], dp[x][j] + 1)
            for y in range(j):
                if sum(grid[i][y] for y in range(j, W)) <= K:
                    dp[i][j] = min(dp[i][j], dp[i][y] + 1)

    return dp[H-1][W-1]

