    dp = [[float('inf')] * (W + 1) for _ in range(H + 1)]
    dp[0][0] = 0

    # Fill the DP table
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            # Calculate the number of white squares in the subgrid (0,0) to (i,j)
            white_squares = sum(grid[x][y] for x in range(i) for y in range(j))
            if white_squares <= K:
                dp[i][j] = 0
            else:
                # Try cutting along rows
                for x in range(1, i):
                    dp[i][j] = min(dp[i][j], dp[x][j] + 1)
                # Try cutting along columns
                for y in range(1, j):
                    dp[i][j] = min(dp[i][j], dp[i][y] + 1)

    return dp[H][W]

