    for _ in range(N):
        current_health = heapq.heappop(max_health)
        for _ in range(current_health - 1):
            heapq.heappush(max_health, current_health - 1)

    # Check if the resulting multiset matches the target multiset
    result_counter = Counter(max_health)
    return result_counter == target_counter

