    target = Counter(S)

    # Helper function to perform backtracking
    def backtrack(current, remaining):
        if not remaining:
            return Counter(current) == target

        # Try each possible health for the current slime
        for health in range(1, remaining[0]):
            current.append(health)
            if backtrack(current, remaining[1:]):
                return True
            current.pop()

        return False

    # Start the backtracking process with an empty list and the full remaining list
    return backtrack([], list(target.elements()))

