    # Initialize the grid
    grid = [[0] * N for _ in range(N)]
    for i in range(1, N-1):
        for j in range(1, N-1):
            grid[i][j] = 1  # Black stones in the central (N-2) x (N-2) square

    # Initialize the bottom and right sides with white stones
    for i in range(N):
        grid[N-1][i] = 0  # Bottom side
        grid[i][N-1] = 0  # Right side

    # Set to keep track of black stones
    black_stones = set()
    for i in range(1, N-1):
        for j in range(1, N-1):
            if grid[i][j] == 1:
                black_stones.add((i, j))

    # Process each query
    for query in queries:
        if query[0] == 1:
            x = query[1]
            for i in range(1, N):
                if grid[i][x-1] == 0:
                    break
                if grid[i][x-1] == 1:
                    black_stones.remove((i, x-1))
                    grid[i][x-1] = 0
            grid[0][x-1] = 0
        elif query[0] == 2:
            x = query[1]
            for j in range(1, N):
                if grid[x-1][j] == 0:
                    break
                if grid[x-1][j] == 1:
                    black_stones.remove((x-1, j))
                    grid[x-1][j] = 0
            grid[x-1][0] = 0

    # Count the number of black stones left
    return len(black_stones)

