def count_unnecessary_cards(N, K, a):
    # Generate all subsets and check if they are good
    good_subsets = set()
    for i in range(1 << N):
        subset_sum = 0
        for j in range(N):
            if i & (1 << j):
                subset_sum += a[j]
        if subset_sum >= K:
            good_subsets.add(i)

    # Check each card for the unnecessary condition
    unnecessary_count = 0
    for i in range(N):
        is_unnecessary = True
        for subset in good_subsets:
            if subset & (1 << i):
                new_subset = subset ^ (1 << i)
                if new_subset not in good_subsets:
                    is_unnecessary = False
                    break
        if is_unnecessary:
            unnecessary_count += 1

    return unnecessary_count

