def count_unnecessary_cards(N, K, a):
    unnecessary_count = 0

    # Generate all subsets
    for r in range(1, N + 1):
        for subset in combinations(a, r):
            if is_good_subset(subset, K):
                # Check if removing any card from this subset still results in a good subset
                for i in range(r):
                    new_subset = list(subset)
                    del new_subset[i]
                    if not is_good_subset(new_subset, K):
