def max_i(s, t):
    if not t:
        return 0
    if not s:
        return -1

    max_i = -1
    len_s = len(s)
    len_t = len(t)

    # Concatenate s with itself until its length is at least as long as t
    concatenated_s = s
    while len(concatenated_s) < len_t:
        concatenated_s += s

    # Check if t is a substring of the concatenated string
    if t in concatenated_s:
        # Find the maximum i such that t is a substring of s repeated i times
        for i in range(1, len_s // len_t + 2):
            if t in s * i:
                max_i = i
            else:
                break

    return max_i

