def dfs(graph, node, visited):
    if visited[node]:
        return
    visited[node] = True
    for neighbor in graph[node]:
        dfs(graph, neighbor, visited)

def min_groups(N, M, friendships):
    if M == 0:
        return N
    if N == 1:
        return 1

    graph = [[] for _ in range(N + 1)]
    for A, B in friendships:
        graph[A].append(B)
        graph[B].append(A)

    visited = [False] * (N + 1)
    groups = 0

    for node in range(1, N + 1):
        if not visited[node]:
            dfs(graph, node, visited)
            groups += 1

    return groups

