    def is_consistent(assignment):
        for i in range(N):
            if s[i] == 'o':
                if assignment[i] == assignment[(i + 1) % N] and assignment[i] == assignment[(i - 1) % N]:
                    continue
                else:
                    return False
            else:
                if assignment[i] != assignment[(i + 1) % N] and assignment[i] != assignment[(i - 1) % N]:
                    continue
                else:
                    return False
        return True

    # Try starting with a sheep
    assignment1 = ['S'] * N
    for i in range(1, N):
        assignment1[i] = 'W' if assignment1[i - 1] == 'S' else 'S'
    if is_consistent(assignment1):
        return ''.join(assignment1)

    # Try starting with a wolf
    assignment2 = ['W'] * N
    for i in range(1, N):
        assignment2[i] = 'S' if assignment2[i - 1] == 'W' else 'W'
    if is_consistent(assignment2):
        return ''.join(assignment2)

    return -1

