def solve(N, s):
    def dfs(node, species, visited, assignment):
        if node in visited:
            return True
        visited.add(node)
        assignment[node] = species

        next_species = 'S' if species == 'W' else 'W'
        if s[node - 1] == 'o':
            if not dfs((node - 2) % N, species, visited, assignment):
                return False
            if not dfs((node + 1) % N, species, visited, assignment):
                return False
        else:
            if not dfs((node - 2) % N, next_species, visited, assignment):
                return False
            if not dfs((node + 1) % N, next_species, visited, assignment):
                return False

        return True

    for start in range(N):
        visited = set()
        assignment = {}
        if dfs(start, 'S', visited, assignment):
            result = ''.join(assignment[i] for i in range(N))
            return result

    return -1

