def can_assign_species(N, s):
    def is_consistent(species):
        for i in range(N):
            if s[i] == 'o':
                if species[i] != species[(i + 1) % N] or species[i] != species[(i - 1) % N]:
                    return False
            else:
                if species[i] == species[(i + 1) % N] and species[i] == species[(i - 1) % N]:
                    return False
        return True

    def backtrack(i, species):
        if i == N:
            return is_consistent(species)
        for species[i] in ['S', 'W']:
            if backtrack(i + 1, species):
                return True
        return False

    species = [''] * N
    if backtrack(0, species):
        return ''.join(species)
    else:
        return -1

