def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (is_prime[p] == True):
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, limit + 1) if is_prime[p]]

def is_similar_to_2017(n, primes):
    if n not in primes:
        return False
    if (n + 1) // 2 not in primes:
        return False
    return True

def count_similar_numbers(l, r, primes):
    count = 0
    for x in range(l, r + 1, 2):
        if is_similar_to_2017(x, primes):
            count += 1
    return count

