from collections import defaultdict, deque

def bfs(graph, start, end, blockships):
    visited = set()
    queue = deque([start])
    visited.add(start)

    while queue:
        current = queue.popleft()
        if current == end:
            return True
        for neighbor in graph[current]:
            if neighbor not in visited and (current, neighbor) not in blockships and (neighbor, current) not in blockships:
                visited.add(neighbor)
                queue.append(neighbor)

    return False

def count_friend_candidates(N, friendships, blockships):
    graph = defaultdict(set)
    for a, b in friendships:
        graph[a].add(b)
        graph[b].add(a)

    friend_candidates = [0] * (N + 1)

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i != j and (i, j) not in friendships and (j, i) not in friendships and (i, j) not in blockships and (j, i) not in blockships:
                if bfs(graph, i, j, blockships):
                    friend_candidates[i] += 1

    return friend_candidates[1:]

