def count_friend_candidates(N, friendships, blockships):
    # Build the friendship graph
    friendship_graph = defaultdict(list)
    for a, b in friendships:
        friendship_graph[a].append(b)
        friendship_graph[b].append(a)

    # Build the blockship graph
    blockship_graph = defaultdict(list)
    for c, d in blockships:
        blockship_graph[c].append(d)
        blockship_graph[d].append(c)

    # Count friend candidates for each user
    friend_candidates = [0] * (N + 1)
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            if a != b:
                if a not in friendship_graph[b] and b not in friendship_graph[a] and b not in blockship_graph[a] and a not in blockship_graph[b]:
                    if bfs(friendship_graph, a, b):
                        friend_candidates[a] += 1

    return friend_candidates[1:]

