def count_friend_candidates(N, friendships, blockships):
    # Initialize adjacency lists for friendships and blockships
    friend_graph = defaultdict(list)
    block_graph = defaultdict(list)

    # Populate the adjacency lists
    for A, B in friendships:
        friend_graph[A].append(B)
        friend_graph[B].append(A)
    for C, D in blockships:
        block_graph[C].append(D)
        block_graph[D].append(C)

    # Function to perform BFS and count friend candidates
    def bfs(start):
        visited = set()
        queue = deque([start])
        reachable = set()

        while queue:
            current = queue.popleft()
            if current in visited:
                continue
            visited.add(current)
            reachable.add(current)

            for neighbor in friend_graph[current]:
                if neighbor not in visited and neighbor not in block_graph[start]:
                    queue.append(neighbor)

        return reachable - {start} - set(friend_graph[start]) - set(block_graph[start])

    # Count friend candidates for each user
    friend_candidates = [0] * (N + 1)
    for i in range(1, N + 1):
        friend_candidates[i] = len(bfs(i))

    return friend_candidates[1:]

