def count_ways_to_choose_sardines(N, sardines):
    if N == 0:
        return 1
    if N == 1:
        return 2

    graph = {i: [] for i in range(N)}

    for i in range(N):
        for j in range(i + 1, N):
            A_i, B_i = sardines[i]
            A_j, B_j = sardines[j]
            if A_i * A_j + B_i * B_j == 0:
                graph[i].append(j)
                graph[j].append(i)

    visited = [False] * N
    total_ways = 1

    for i in range(N):
        if not visited[i]:
            component_size = dfs(i, visited, graph)
            total_ways = (total_ways * (2**component_size - 1)) % MOD

    return total_ways

