def count_ways(N, sardines):
    if N == 1:
        return 2  # Either choose the sardine or not choose it

    # Initialize adjacency list
    adj = [[] for _ in range(N)]

    # Build the graph
    for i in range(N):
        for j in range(i + 1, N):
            if sardines[i][0] * sardines[j][0] + sardines[i][1] * sardines[j][1] == 0:
                adj[i].append(j)
                adj[j].append(i)

    # Dynamic programming to count the number of ways
    dp = [[0, 0] for _ in range(N)]
    dp[0][0] = 1  # Not choosing the first sardine
    dp[0][1] = 1  # Choosing the first sardine

    for i in range(1, N):
        dp[i][0] = sum(dp[j][1] for j in adj[i]) % MOD  # Not choosing the i-th sardine
        dp[i][1] = sum(dp[j][0] for j in adj[i]) % MOD  # Choosing the i-th sardine

    # Sum up all possible ways to choose the sardines
    result = sum(dp[i][0] + dp[i][1] for i in range(N)) % MOD
    return result

