def count_independent_sets(n, edges):
    from collections import defaultdict
    from bitarray import bitarray

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize dp array
    dp = [bitarray([1, 1]) for _ in range(n)]

    # Process each node
    for i in range(n):
        for j in range(i):
            if (i, j) in edges or (j, i) in edges:
                dp[i][1] = (dp[i][1] + dp[j][0]) % MOD

    # Sum up all valid independent sets
    result = sum(dp[i][0] + dp[i][1] for i in range(n)) % MOD
    return result

