class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        pu, pv = self.find(u), self.find(v)
        if pu == pv:
            return False
        if self.size[pu] < self.size[pv]:
            pu, pv = pv, pu
        self.parent[pv] = pu
        self.size[pu] += self.size[pv]
        return True

def count_ways(N, sardines):
    uf = UnionFind(N)
    for i in range(N):
        for j in range(i + 1, N):
            A1, B1 = sardines[i]
            A2, B2 = sardines[j]
            if A1 * A2 + B1 * B2 == 0:
                uf.union(i, j)

    component_sizes = [0] * N
    for i in range(N):
        component_sizes[uf.find(i)] += 1

    result = 1
    for size in component_sizes:
        if size > 0:
            result = (result * (2**size - 1)) % MOD

    return result

