    # Find the position of the smallest element
    min_val = min(P)
    min_index = P.index(min_val)

    # If the smallest element is already at the beginning, sort the rest
    if min_index == 0:
        for i in range(1, N):
            if P[i] < P[i - 1]:
                return -1
        return []

    # Move the smallest element to the beginning
    swaps = []
    for i in range(min_index):
        swaps.append(min_index - i)
        P[min_index - i], P[min_index - i - 1] = P[min_index - i - 1], P[min_index - i]

    # Sort the rest of the permutation
    for i in range(1, N):
        if P[i] < P[i - 1]:
            return -1
        for j in range(i, 0, -1):
            if P[j] < P[j - 1]:
                swaps.append(j)
                P[j], P[j - 1] = P[j - 1], P[j]

    return swaps

