def find_unbalanced_substring(s):
    n = len(s)
    for length in range(2, n + 1):
        char_count = {}
        for i in range(length):
            char_count[s[i]] = char_count.get(s[i], 0) + 1
        if any(count > length // 2 for count in char_count.values()):
            return 1, length

        for start in range(1, n - length + 1):
            char_count[s[start - 1]] -= 1
            if char_count[s[start - 1]] == 0:
                del char_count[s[start - 1]]
            char_count[s[start + length - 1]] = char_count.get(s[start + length - 1], 0) + 1
            if any(count > length // 2 for count in char_count.values()):
                return start, start + length

    return -1, -1

